function handleAcks(d){let changed=false;const all=buildDrafts();for(const [k,a] of Object.entries(d.buildAcks?.[uid]||{})){if(ackDone.has(k))continue;ackDone.add(k);if(a?.status!=='approved')continue;for(const [t,f] of Object.entries(all.topics)){if(f.requestKey2===k){for(const x of ['requestKey2','q','opts','explain'])delete f[x];if($('topic').value===t)for(const x of ['q','opts','explain'])$(x).value='';changed=true}if(f.requestKey3===k){for(const x of ['requestKey3','buildMeaning'])delete f[x];if($('landmarkTopic').value===t)$('buildMeaning').value='';changed=true}}}if(changed){local.set(buildDraftKey(),JSON.stringify(all));saveDraft()}}
for(const id of ['q','opts','explain','answer'])$(id).addEventListener(id==='answer'?'change':'input',()=>saveBuildDraft($('topic').value,{[id]:$(id).value}));
$('topic').addEventListener('change',()=>{if(roomData)refreshBuildTopics(roomData,roomData.game)});$('landmarkTopic').addEventListener('change',()=>{if(roomData)refreshBuildTopics(roomData,roomData.game)});
$('buildMeaning').addEventListener('input',()=>saveBuildDraft($('landmarkTopic').value,{buildMeaning:$('buildMeaning').value}));document.querySelectorAll('input[name="buildIcon"]').forEach(x=>x.addEventListener('change',()=>saveBuildDraft($('landmarkTopic').value,{buildIcon:x.value})));
// 공사 요청 보내기: 고유 push 키, 주인 팀·땅 버전 포함. 성공해도 초안은 승인 확인 때까지 남김
async function sendBuild(level,topic,fields){const d=roomData,g=d?.game;if(!d||host)return;const myTeam=Number(d.members?.[uid]?.team??-1);if(Object.values(d.buildRequests||{}).some(r=>Number(r?.ownerTeam)===myTeam))return alert(BUILD_REASONS.busy);const made=makeBuildRequest({uid,nickname:d.members?.[uid]?.nickname,team:myTeam,g,topic,level,fields,now:Date.now()});if(!made.ok)return alert(made.message);const pre=buildPrecheck(g,made.request);if(!pre.ok)return alert(pre.message);if(offline())return;try{const r=push(ref(db,'rooms/'+room+'/buildRequests'));await set(r,made.request);saveBuildDraft(String(topic),{['requestKey'+level]:r.key});notify('📨 LV'+level+' 공사 요청을 보냈어요. 친구 검토 → 선생님 승인 뒤 반영돼요. 초안은 승인될 때까지 남아 있어요.')}catch(e){alert('공사 요청 오류: '+e.message+' (초안은 그대로예요)')}}
$('buildLv3Submit').onclick=()=>sendBuild(3,+$('landmarkTopic').value,{icon:document.querySelector('input[name="buildIcon"]:checked')?.value||'',meaning:$('buildMeaning').value});
// resumed: 서버에서 이미 확인한 내 참가 정보(같은 기기 재입장). 있으면 입력 칸 값으로 참가 정보를 덮어쓰지 않음
async function enter(code,isHost,resumed=null){const room=code.toUpperCase().trim();let r=ref(db,'rooms/'+room);if(isHost){const snapshot=await get(r);if(!snapshot.exists()||snapshot.val().hostUid!==uid)throw Error('이 방의 교사 권한이 없습니다. 방을 만든 브라우저에서 접속하세요.');}let me=null;if(!isHost&&resumed){$('nick').value=resumed.nickname;$('team').value=String(resumed.team);me={nickname:resumed.nickname,team:resumed.team};}if(!isHost&&!resumed){const nick=$('nick').value.trim(),team=+$('team').value;if(!nick||nick.length>20)throw Error('별명을 1~20자로 입력하세요.');const snapshot=await get(r);if(!snapshot.exists())throw Error('존재하지 않는 방입니다.');const d=snapshot.val();const roomCfg=roomConfig(d);setTeamOptions(roomCfg,team,room);if(!isTeamIndex(team,roomCfg))throw Error(wrongTeamMessage(roomCfg));if(d.hostUid===uid)throw Error('이 브라우저는 이 방의 교사로 접속 중입니다. 학생은 다른 기기나 별도 브라우저 프로필에서 입장해 주세요.');const currentMember=d.members?.[uid];if(currentMember&&(currentMember.nickname!==nick||Number(currentMember.team)!==team))throw Error('이 브라우저에서 이미 '+currentMember.nickname+' 학생이 참가 중입니다. 기존 학생 화면의 나가기 버튼을 누른 뒤 다시 입장해 주세요.');const existing=Object.entries(d.members||{}).filter(([id])=>id!==uid&&id!==d.hostUid);if(existing.filter(([id,m])=>Number(m.team)===team).length>=10)throw Error('이 팀은 이미 10명이 참가했습니다.');const key=Array.from(new TextEncoder().encode(nick.toLowerCase())).map(x=>x.toString(16).padStart(2,'0')).join('');const nickRef=ref(db,'rooms/'+room+'/nicknames/'+key);const reserved=await runTransaction(nickRef,v=>v===null?uid:v===uid?uid:undefined,{applyLocally:false});if(!reserved.committed)throw Error('이미 사용 중인 별명입니다. 다른 별명을 입력하세요.');
// 참가 정보 쓰기 직전에 방 설정을 다시 확인(설정은 방을 만들 때 한 번만 저장되고 바뀌지 않음)
const latest=roomConfig({config:(await get(ref(db,'rooms/'+room+'/config'))).val()});if(!isTeamIndex(team,latest)){setTeamOptions(latest,team,room);throw Error(wrongTeamMessage(latest))}
try{await set(ref(db,'rooms/'+room+'/members/'+uid),{nickname:nick,team,joinedAt:d.members?.[uid]?.joinedAt||Date.now()})}catch(e){if(/permission/i.test(String(e?.code||e?.message)))throw Error('서버 규칙 때문에 '+teamLabel(latest.teamNames[team])+'(으)로 입장하지 못했어요. 다른 팀을 고르거나 선생님께 알려 주세요. (5팀 방은 선생님이 최신 Firebase 규칙을 게시해야 해요)');throw e}
me={nickname:nick,team};}
enterRoom(room,isHost,r,me);}
const wrongTeamMessage=c=>'이 방은 '+c.label+' '+c.teamCount+'팀 방이에요. 팀 목록에서 다시 골라 주세요.';
function enterRoom(code,isHost,r,me=null){room=code;host=isHost;pendingResume=null;if(unsub)unsub();unsub=onValue(r,s=>{if(room!==code)return;if(!s.exists()){roomGone('방이 없어졌어요. 방 코드를 확인하고 다시 입장해 주세요.');return}const val=s.val(),sig=JSON.stringify({...val,hostBeat:0});if(roomData&&sig===roomSig){roomData=val;updateHostIndicator();return}roomSig=sig;roomData=val;applyConfig(roomConfig(roomData));if(!host&&!roomData.members?.[uid]){if(!leavingRoom)roomGone('참가 정보가 없어졌어요. 별명과 나라를 선택해 다시 입장해 주세요.');return}notify('🟢 '+room+' 실시간 연결 중');draw();if(host){processLeavingMembers().catch(e=>notify('나가기 처리 오류: '+e.message));processAttempts().catch(e=>notify('처리 오류: '+e.message));processRollRequests().catch(e=>notify('주사위 처리 오류: '+e.message));processAuthoringRequests().catch(e=>notify('출제중 처리 오류: '+e.message));processCompletedQuestions().catch(e=>notify('출제 완료 처리 오류: '+e.message));processLandmarkProposals().catch(e=>notify('꾸미기 반영 오류: '+e.message));processBuildRequests().catch(e=>notify('공사 요청 처리 오류: '+e.message));scheduleAutoHandoff();startHostLoop();hostTick()}},e=>notify('접속 오류: '+e.message+' · 새로고침하면 같은 기기에서 다시 들어올 수 있어요.'));if(!host&&!me)me={nickname:$('nick').value.trim(),team:+$('team').value};local.set(PROFILE_KEY,JSON.stringify(makeProfile({uid,room,host,...(host?{}:me)})));tabStore.remove('historyRoom');tabStore.remove('historyHost');hideResumeCard();restoreDraft();}
// 이 브라우저의 방 이어하기 저장값과 초안 삭제(나가기·잊기·확정된 무효일 때만)
function forgetRoom(){local.remove(PROFILE_KEY);local.remove(DRAFT_KEY);tabStore.remove('historyRoom');tabStore.remove('historyHost');pendingResume=null;}
function closeRoomView(){if(unsub){unsub();unsub=null}stopHostLoop();clearInterval(quizTicker);quizTicker=null;roomSig='';lv2Topic='';lv3Topic='';$('buildPanel')?.classList.add('hidden');$('myStatus')?.classList.add('hidden');dismissTurnAlert();applyConfig(legacyConfig());autoHandoffKey='';autoOpenClaimKey='';$('turnBanner')?.remove();clearTimeout(turnBannerTimer);turnBannerKey='';effectState=null;effectTimers.forEach(clearTimeout);effectTimers=[];pendingRollKey='';roomData=null;host=false;room='';lastQRRoom='';$('game').classList.add('hidden');for(const id of ['author','landmarkEditor','teacher','teacherProgress','myRollShortcut','finalResults','reopenResults'])$(id)?.classList.add('hidden');$('lobby').classList.remove('hidden');}
function roomGone(message){const code=room;forgetRoom();closeRoomView();$('roomCode').value=code;lookupRoomTeams();notify('⚠️ '+message);}
function saveDraft(){if(!room||!uid)return;const fields={q:$('q').value,opts:$('opts').value,explain:$('explain').value,answer:$('answer').value,topic:$('topic').value,landmarkName:$('landmarkName').value,landmarkImage:$('landmarkImage').value};if(draftIsEmpty(fields)){local.remove(DRAFT_KEY);return}local.set(DRAFT_KEY,JSON.stringify(makeDraft({uid,room,fields})));}
function restoreDraft(){
 const f=parseDraft(local.get(DRAFT_KEY),uid,room);if(!f)return;
 // 예전 단일 초안을 다른 거점에 끼워 넣지 않음. 원래 거점이 선택 가능할 때만 옮김.
 const topic=String(f.topic??''),valid=[...$('topic').options].some(o=>o.value===topic);
 if(valid&&!buildDrafts().topics[topic]){
  saveBuildDraft(topic,Object.fromEntries(['q','opts','explain','answer'].map(k=>[k,f[k]||''])));
  $('topic').value=topic;lv2Topic='';refreshBuildTopics(roomData,roomData.game);
 }
 for(const id of ['landmarkName','landmarkImage'])if(f[id]&&!$(id).value)$(id).value=f[id];
}

for(const id of ['q','opts','explain','answer','topic','landmarkName','landmarkImage'])$(id).addEventListener(id==='answer'||id==='topic'?'change':'input',saveDraft);
function showResumeCard(p,text,busy=false){$('resumeCard').classList.remove('hidden');$('resumeText').textContent=text;$('resumeGo').textContent='↩️ '+(p.host?'교사 방':'이전 방')+' '+p.room+'(으)로 돌아가기'+(p.host?'':' · '+(p.nickname||'')+' / '+(names[p.team]||(Number(p.team)+1)+'번 팀'));$('resumeGo').disabled=busy;$('resumeGo').onclick=()=>tryResume(p);$('resumeForget').textContent=p.host?'🧹 이 기기에서 잊기':'🧹 다른 학생으로 접속 · 이 기기에서 잊기';}
function hideResumeCard(){$('resumeCard')?.classList.add('hidden')}
// 저장된 방으로 다시 들어가기: 서버에서 hostUid·members/{uid}를 확인한 뒤에만 입장
async function tryResume(p){if(resumeBusy||room)return;if(!uid){pendingResume=p;showResumeCard(p,'⏳ 서버 연결을 기다리는 중이에요. 연결되면 자동으로 다시 들어가요.',true);return}resumeBusy=true;pendingResume=p;showResumeCard(p,'⏳ 이전 방 '+p.room+'에 다시 연결하는 중…',true);try{let d;try{d=(await get(ref(db,'rooms/'+p.room))).val()}catch(e){showResumeCard(p,'📶 연결이 불안정해요. 연결되면 자동으로 다시 들어가요. (저장된 참가 정보는 그대로예요)');return}if(pendingResume!==p)return;const check=checkRoom(d,uid,p.host);if(!check.ok){forgetRoom();hideResumeCard();$('roomCode').value=p.room;if(!p.host){$('nick').value=p.nickname||'';setTeamOptions(roomConfig(d),p.team,p.room)}notify('⚠️ '+check.message);return}pendingResume=null;if(!p.host)setTeamOptions(roomConfig(d),check.member?.team,p.room);try{await enter(p.room,p.host,check.member||null);notify('🟢 같은 기기에서 다시 입장했어요 · '+p.room)}catch(e){pendingResume=p;showResumeCard(p,'다시 입장하지 못했어요: '+e.message)}}finally{resumeBusy=false}}
// 공용 기기: 이 기기의 이어하기 정보만 지움(서버의 팀 참가 정보는 그대로). 학생은 새 익명 계정으로 바꿔 다른 학생이 입장할 수 있게 함
async function forgetDevice(){const p=parseProfile(local.get(PROFILE_KEY),uid)||pendingResume,isHost=room?host:!!p?.host;if(!confirm(isHost?'이 기기에서 교사 방 자동 재입장 정보를 지울까요?\n(교사 권한과 방은 그대로예요)':'이 기기에서 지금 학생의 접속 정보를 지울까요?\n팀에서 나가지는 않아요. 팀을 바꾸려면 ‘나가기’를 쓰세요.\n지운 뒤 다른 학생이 이 기기로 새로 입장할 수 있어요.'))return;forgetRoom();if(room)closeRoomView();hideResumeCard();$('nick').value='';if(!isHost&&auth){try{await signOut(auth)}catch{}uid=null;try{await signInAnonymously(auth)}catch{}uid=auth.currentUser?.uid||null}notify(uid?'🧹 이 기기에서 잊었어요. 새 학생은 별명과 나라를 고르고 입장하세요.':'🧹 이 기기에서 잊었어요. 연결되면 새 학생으로 입장할 수 있어요.');}
function watchConnection(){onValue(ref(db,'.info/serverTimeOffset'),s=>{serverOffset=Number(s.val())||0});onValue(ref(db,'.info/connected'),s=>{connected=s.val()===true;if(connected)everConnected=true;const el=$('conn');if(el){el.textContent=connected?'🟢 서버 연결됨':everConnected?'🔴 연결이 끊겼어요 · 자동으로 다시 연결하는 중 (닫아도 이 기기에서 다시 들어올 수 있어요)':'⏳ 서버에 연결하는 중…';el.classList.toggle('offline',!connected)}if(connected&&!auth.currentUser)signInAnonymously(auth).catch(()=>{});if(connected&&pendingResume&&!room)tryResume(pendingResume)});}
// 새 방: 교사가 고른 시대·팀 수·팀 이름을 방을 만들 때 한 번만 저장(이후 바꾸지 않음). 기존 방에는 적용하지 않음
$('create').onclick=async()=>{if(!uid)return alert('연결을 기다려 주세요.');const built=buildRoomConfig({scenario:$('scenario').value,teamCount:+$('teamCount').value,teamNames:Array.from({length:MAX_TEAMS},(_,i)=>$('teamName'+i).value),quizSeconds:+$('quizSeconds').value,resultSeconds:+$('resultSeconds').value});if(!built.ok)return alert(built.message);const config=built.config,bank=questionBankFor(roomConfig({config}),DEFAULT_QUESTIONS,SCENARIO_QUESTIONS);if(bank.length<24)return alert('이 시대의 문제 자료를 불러오지 못했어요.');let code=Math.random().toString(36).slice(2,8).toUpperCase();try{await set(ref(db,'rooms/'+code),{hostUid:uid,createdAt:Date.now(),config,members:{[uid]:{nickname:$('nick').value.trim()||'선생님',team:0}},questions:bank,game:initialGame(config.teamCount,Date.now())});await enter(code,true)}catch(e){alert('방 생성 오류: '+e.message)}};
$('join').onclick=async()=>{let code=$('roomCode').value.trim().toUpperCase();if(!/^[A-Z0-9]{6}$/.test(code))return alert('6자리 방 코드를 입력하세요.');if(!uid)return alert('연결을 기다려 주세요.');try{await enter(code,false)}catch(e){alert('입장 오류: '+e.message)}};
$('copy').onclick=()=>navigator.clipboard?.writeText(room).then(()=>alert('방 코드를 복사했습니다.'));
$('leaveRoom').onclick=async()=>{if(host||!room||!uid)return;if(offline())return;const code=room,member=roomData?.members?.[uid];if(!confirm('현재 '+names[Number(member?.team)||0]+' 팀에서 나와 다시 나라를 선택할까요? 방과 점령 기록은 그대로 유지됩니다.'))return;leavingRoom=true;try{const nick=member?.nickname||'';await update(ref(db,'rooms/'+code+'/members/'+uid),{leaving:true});await new Promise((resolve,reject)=>{let stop;const timer=setTimeout(()=>{stop?.();reject(Error('교사 화면을 켜 둔 뒤 다시 나가기를 눌러 주세요.'))},12000);stop=onValue(ref(db,'rooms/'+code+'/members/'+uid),s=>{if(!s.exists()){clearTimeout(timer);stop?.();resolve()}},e=>{clearTimeout(timer);stop?.();reject(e)})});forgetRoom();closeRoomView();$('roomCode').value=code;$('nick').value=nick;lookupRoomTeams();notify('🟢 팀에서 나왔습니다. 팀을 다시 선택하고 학생: 방 입장을 누르세요.')}catch(e){alert('나가기 오류: '+e.message)}finally{leavingRoom=false}};
$('forgetDevice').onclick=()=>forgetDevice();$('resumeForget').onclick=()=>forgetDevice();

let leaveProcessing=false;
async function processLeavingMembers(){
 if(leaveProcessing||!host||!roomData)return;leaveProcessing=true;
 try{for(const [id,member] of Object.entries(roomData.members||{})){
  if(id===roomData.hostUid||member.leaving!==true)continue;
  const changes={};
  for(const key of ['rollRequests','authoringRequests','attempts'])changes[key+'/'+id]=null;
  for(const [key,owner] of Object.entries(roomData.nicknames||{}))if(owner===id)changes['nicknames/'+key]=null;
  changes['members/'+id]=null;
  await update(ref(db,'rooms/'+room),changes);
 }}finally{leaveProcessing=false;}
}
function canStartAuthoring(d,g,actor=uid,teacher=host){const claim=d?.pendingClaims?.[g?.questionId];return !!(g?.phase==='author'&&claim&&Number(claim.team)===Number(g.team)&&Number(g.owners?.[g.questionId]??-1)<0&&(teacher||Number(d.members?.[actor]?.team)===Number(g.team)));}
async function handoffAuthoring(expected){return runTransaction(ref(db,'rooms/'+room+'/game'),old=>handoffTransform(old,expected,ctx()),{applyLocally:false});}
// 교사 화면: 출제(author)·출제 대기(wait)를 보면 주사위 연출이 끝난 뒤 자동으로 한 번만 다음 차례로(트랜잭션 CAS라 중복 스냅숏·새로고침에도 한 번)
let autoHandoffKey='';
function scheduleAutoHandoff(){const d=roomData,g=d?.game;if(!host||!shouldAutoHandoff(d,g))return;const key=room+':'+handoffKey(g);if(autoHandoffKey===key)return;autoHandoffKey=key;const delay=Math.min(2600,Math.max(0,Number(g.rollStartedAt||0)+2600-Date.now()));setTimeout(()=>{const now=roomData?.game;if(!host||room+':'+handoffKey(now)!==key||!shouldAutoHandoff(roomData,now))return;handoffAuthoring(now).catch(e=>{autoHandoffKey='';notify('자동 넘김 오류: '+e.message)})},delay);}
let authoringProcessing=false;async function processAuthoringRequests(){if(authoringProcessing||!host||!roomData?.authoringRequests)return;authoringProcessing=true;try{const d=roomData,g=d.game;for(const [id,v] of Object.entries(d.authoringRequests)){const current=g.phase==='author'&&v.turnId===g.turnId&&v.topic===g.questionId&&v.team===g.team&&canStartAuthoring(d,g,id,false);if(!current){await remove(ref(db,'rooms/'+room+'/authoringRequests/'+id));continue}await handoffAuthoring(g);await remove(ref(db,'rooms/'+room+'/authoringRequests/'+id));break}}finally{authoringProcessing=false}}
